function usePetals(ref) {
    useEffect(() => {
        const c = ref.current;
        if (!c || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return undefined;
        const x = c.getContext('2d');
        let W = 0, H = 0, raf = 0;
        const size = () => { const d = window.devicePixelRatio || 1; W = window.innerWidth; H = window.innerHeight; c.width = W * d; c.height = H * d; c.style.width = `${W}px`; c.style.height = `${H}px`; x.setTransform(d, 0, 0, d, 0, 0); };
        size(); window.addEventListener('resize', size);
        const P = Array.from({ length: Math.round(Math.min(28, Math.max(12, window.innerWidth / 60))) }, () => ({ x: Math.random() * W, y: Math.random() * H, s: 5 + Math.random() * 7, vy: 0.2 + Math.random() * 0.35, vx: -0.15 + Math.random() * 0.3, r: Math.random() * 6.3, vr: -0.01 + Math.random() * 0.02, w: Math.random() * 6.3 }));
        const root = c.closest('.ny');
        const f = () => {
            x.clearRect(0, 0, W, H);
            x.fillStyle = (root && getComputedStyle(root).getPropertyValue('--rose').trim()) || '#ec8fa2';
            x.globalAlpha = 0.28;
            for (const p of P) {
                p.y += p.vy; p.w += 0.02; p.x += p.vx + Math.sin(p.w) * 0.3; p.r += p.vr;
                if (p.y > H + 20) { p.y = -20; p.x = Math.random() * W; }
                x.save(); x.translate(p.x, p.y); x.rotate(p.r); x.beginPath(); x.moveTo(0, -p.s);
                x.bezierCurveTo(p.s * 0.9, -p.s * 0.6, p.s * 0.7, p.s * 0.7, 0, p.s); x.bezierCurveTo(-p.s * 0.7, p.s * 0.7, -p.s * 0.9, -p.s * 0.6, 0, -p.s); x.fill(); x.restore();
            }
            raf = requestAnimationFrame(f);
        };
        f();
        return () => { cancelAnimationFrame(raf); window.removeEventListener('resize', size); };
    }, [ref]);
}

/** The live Quran Echoes demo: the real API, the real approved passages. */
function TryIt() {
    const { t: tr } = useTranslation('niyyah');
    const [text, setText] = useState('');
    const [busy, setBusy] = useState(false);
    const [result, setResult] = useState(null);
    const [missed, setMissed] = useState(false);
    const [asked, setAsked] = useState('');
    const [shared, setShared] = useState(false);
    const [failed, setFailed] = useState(false);
    const out = useRef(null);
    const run = async (q = text) => {
        if (!q.trim()) return;
        setBusy(true); setFailed(false); setResult(null); setMissed(false); setShared(false);
        try {
            const r = await fetch(API, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text: q }) });
            if (!r.ok) throw new Error(String(r.status));
            setResult(await r.json()); setAsked(q);
            setTimeout(() => out.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }), 80);
        } catch { setFailed(true); } finally { setBusy(false); }
    };
    return (
        <div className="try">
            <div className="reveal">
                <span className="eyebrow">{tr('try.eyebrow')}</span>
                <h2 style={{ marginTop: 14 }}><Trans t={tr} i18nKey="try.h2" components={RICH} /></h2>
                <p className="lede" style={{ marginTop: 18 }}>{tr('try.lede')}</p>
                <div className="glass box" style={{ marginTop: 28 }}>
                    <textarea value={text} maxLength={500} onChange={(e) => setText(e.target.value)} placeholder={tr('try.placeholder')} aria-label={tr('try.inputLabel')} />
                    <div className="chips">{tr('try.examples', { returnObjects: true }).map((e) => <button key={e} type="button" className="chip" onClick={() => { setText(e); run(e); }}>{e}</button>)}</div>
                    <button type="button" className="btn gold" style={{ width: '100%' }} disabled={busy || !text.trim()} onClick={() => run()}>{busy ? tr('try.listening') : tr('try.find')}</button>
                </div>
            </div>
            <div ref={out} aria-live="polite" style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                {busy && <div className="skel" />}
                {failed && (
                    <div className="glass box"><p className="lede" style={{ fontSize: 16 }}><Trans t={tr} i18nKey="try.failed" components={{ a: <a href={APP} style={{ color: 'var(--gold)' }}>alexa.imuslimlife.com/niyyah</a> }} /></p></div>
                )}
                {result?.kind === 'crisis' && (
                    <div className="alert" role="alert">
                        <h3>{tr('try.crisisH')}</h3>
                        <p style={{ margin: '8px 0 0' }}>{tr('try.crisisP')}</p>
                        <p style={{ margin: '8px 0 0' }}>{(result.resources || []).map((r) => <span key={r.label}><b>{r.label}:</b> {r.contact}<br /></span>)}</p>
                    </div>
                )}
                {result?.kind === 'ruling' && (
                    <div className="glass box"><span className="eyebrow">{tr('try.rulingEyebrow')}</span><h3 style={{ marginTop: 10 }}>{tr('try.rulingH')}</h3><p className="lede" style={{ fontSize: 16, marginTop: 8 }}>{tr('try.rulingP')}</p></div>
                )}
                {result?.kind === 'none' && (
                    <div className="glass box"><p className="lede" style={{ fontSize: 16 }}>{tr('try.none')}</p></div>
                )}
                {result?.kind === 'themes' && result.results.slice(0, 1).map((r) => (
                    <article key={r.passage.ref} className="glass box verse">
                        <div className="ref"><span className="eyebrow">{r.theme.name}</span><span style={{ color: 'var(--muted)', fontSize: 14 }}>{r.passage.surahName?.en || tr('try.surah')} {r.passage.ref}</span></div>
                        <p className="ar" lang="ar">{r.passage.ayahs.map((a) => <span key={a.ayah}>{a.ar} <span className="mk">﴿{arNum(a.ayah)}﴾</span> </span>)}</p>
                        <div className="rosette" aria-hidden="true"><Rose /></div>
                        <p className="en">{r.passage.ayahs.map((a) => a.translation && <span key={a.ayah}><sup>{a.ayah}</sup>{a.translation} </span>)}</p>
                        {r.passage.tafsir && (
                            // Full note, never shortened (QuranEnc terms); the API sends it once loaded.
                            <details className="tafsir" onToggle={(e) => { if (e.currentTarget.open) ping(r.theme.id, 'tafsir'); }}>
                                <summary>{tr('try.tafsir')} · {r.passage.tafsir.name}</summary>
                                <div dir={r.passage.tafsir.edition.startsWith('en.') ? 'ltr' : 'rtl'} lang={r.passage.tafsir.edition.slice(0, 2)}>
                                    {r.passage.tafsir.notes.map((n) => <p key={n.from}>{!/^\[?\d+[\].]/.test(n.text) && <sup>{n.from === n.to ? n.from : `${n.from}–${n.to}`} </sup>}{n.text}</p>)}
                                </div>
                                <div className="credit">{r.passage.tafsir.credit}</div>
                            </details>
                        )}
                        <p className="q">{r.reflection}</p>
                        <p className="note">{result.note}</p>
                        <div className="ctas" style={{ marginTop: 18 }}><a className="btn gold" href={APP} onClick={() => ping(r.theme.id, 'plan')}>{tr('try.plan')}</a></div>
                        {missed
                            ? <p className="note">{tr('try.missThanks')}</p>
                            : <button type="button" className="note" style={{ background: 'none', border: 0, padding: 0, marginTop: 12, cursor: 'pointer', textDecoration: 'underline' }} onClick={() => { ping(r.theme.id, 'miss'); setMissed(true); }}>{tr('try.miss')}</button>}
                    </article>
                ))}
                {result && result.kind !== 'crisis' && (
                    // Opt-in only (feedback step 5): kept without a name, for 30 days, to improve matching.
                    <label className="note" style={{ display: 'flex', gap: 8, alignItems: 'flex-start', cursor: 'pointer', marginTop: 4 }}>
                        <input type="checkbox" checked={shared} disabled={shared} style={{ marginTop: 3 }} onChange={() => {
                            if (shared || !asked) return;
                            setShared(true);
                            fetch(API.replace(/echoes$/, 'share'), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: asked }) }).catch(() => {});
                        }} />
                        <span>{shared ? tr('try.shared') : tr('try.share')}</span>
                    </label>
                )}
                {!result && !busy && !failed && (
                    <div className="glass box verse" style={{ opacity: 0.92 }}>
                        <span className="eyebrow">{tr('try.example')}</span>
                        <p className="ar" lang="ar">{AYAH_13_28_AR} <span className="mk">﴿{arNum(28)}﴾</span></p>
                        <div className="rosette" aria-hidden="true"><Rose /></div>
                        {tr('ayah.en') && <p className="en"><sup>28</sup>{tr('ayah.en')}</p>}
                        <p className="q">{tr('try.exampleQ')}</p>
                        <p className="note">{tr('try.exampleSrc')}</p>
                    </div>
                )}
            </div>
        </div>
    );
}

const NiyyahPage = () => {
    const [period, setPeriod] = useState('fajr');
    const [open, setOpen] = useState(0);
    const [shot, setShot] = useState(0);
    const root = useRef(null);
    const petals = useRef(null);
    usePetals(petals);
    const { t, i18n } = useTranslation('niyyah');
    const lang = i18n.resolvedLanguage || 'en';
    useEffect(() => loadFont(SCRIPT_FONTS[lang]), [lang]);

    useEffect(() => {
        // /niyyah#try (the home card's 'Try Quran Echoes') opens at the live demo.
        const target = window.location.hash === '#try' ? document.getElementById('try') : null;
        if (target) setTimeout(() => target.scrollIntoView({ block: 'start' }), 120); else window.scrollTo(0, 0);
        loadFont(FONTS);
        const el = root.current;
        // The sky follows the section in view: one scroll is one day.
        const skies = new IntersectionObserver((entries) => {
            entries.forEach((e) => { if (e.isIntersecting) setPeriod(e.target.dataset.sky); });
        }, { rootMargin: '-45% 0px -45% 0px' });
        el.querySelectorAll('[data-sky]').forEach((s) => skies.observe(s));
        const reveal = new IntersectionObserver((entries) => entries.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('seen'); reveal.unobserve(e.target); } }), { threshold: 0.15 });
        el.querySelectorAll('.reveal').forEach((s) => reveal.observe(s));
        // The roses open one by one when the week comes into view.
        let timer = null;
        const week = new IntersectionObserver(([e]) => {
            if (!e.isIntersecting || timer) return;
            let n = 0; timer = setInterval(() => { n += 1; setOpen(n); if (n >= 5) clearInterval(timer); }, 420);
        }, { threshold: 0.5 });
        const w = el.querySelector('.week'); if (w) week.observe(w);
        const slides = setInterval(() => setShot((s) => (s + 1) % 3), 4200);
        return () => { skies.disconnect(); reveal.disconnect(); week.disconnect(); clearInterval(timer); clearInterval(slides); };
    }, []);

    const faq = t('faq.items', { returnObjects: true });
    const faqSchema = { '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: faq.map(({ q, a }) => ({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: a } })) };
    // Fri…Thu in the page's language (2027-01-01 is a Friday).
    const dayFmt = new Intl.DateTimeFormat(lang, { weekday: 'short', timeZone: 'UTC' });
    const days = Array.from({ length: 7 }, (_, i) => dayFmt.format(Date.UTC(2027, 0, 1 + i)));
    const shotAlts = t('week.shots', { returnObjects: true });
    const shots = ['today', 'plan', 'dhuhr'].map((f, i) => [f, shotAlts[i]]);
    const rich = (key) => <Trans t={t} i18nKey={key} components={RICH} />;

    return (
        <div className="ny" data-p={period} ref={root}>
            <Helmet>
                <title>{t('meta.title')}</title>
                <meta name="description" content={t('meta.description')} />
                <meta property="og:title" content={t('meta.title')} />
                <meta property="og:description" content={t('meta.description')} />
                <meta name="twitter:title" content={t('meta.title')} />
                <meta name="twitter:description" content={t('meta.description')} />
            </Helmet>
            <style>{css}</style>
            <script type="application/ld+json">{JSON.stringify(faqSchema)}</script>
            <div className="bg" aria-hidden="true">
                {PERIODS.map((p) => <div key={p} className={`sky ${p}${p === period ? ' on' : ''}`} />)}
                <div className="stars" /><div className="lattice" />
            </div>
            <canvas className="petals" ref={petals} aria-hidden="true" />
            <div className="clock glass" aria-hidden="true"><b>{PERIOD_AR[period]}</b>{t(`periods.${period}`)}</div>

            <section data-sky="fajr">
                <div className="wrap hero">
                    <div>
                        <div className="arch">
                            <svg viewBox="0 0 300 340" fill="none" stroke="var(--gold)" aria-hidden="true">
                                <path d="M20 338V140C20 74 90 36 150 6c60 30 130 68 130 134v198" strokeWidth="1.6" />
                                <path className="thin" d="M34 338V144C34 88 96 54 150 24c54 30 116 64 116 120v194" strokeWidth=".8" opacity=".6" />
                            </svg>
                            <div className="in"><div className="crescent" /><div className="bism" lang="ar">{BISMILLAH}</div></div>
                        </div>
                        <span className="eyebrow rise" style={{ animationDelay: '.4s' }}>{t('hero.eyebrow')} <span className="ar">نِيَّة</span></span>
                        <h1 className="rise" style={{ marginTop: 16, animationDelay: '.6s' }}>{rich('hero.h1')}</h1>
                        <p className="lede rise" style={{ marginTop: 24, animationDelay: '.9s' }}>{t('hero.lede')}</p>
                        <div className="ctas rise" style={{ animationDelay: '1.1s' }}>
                            <a className="btn gold" href={APP}>{t('hero.begin')}</a>
                            <a className="btn ghost" href="#try">{t('hero.tryEchoes')}</a>
                        </div>
                        <p className="rise" style={{ fontSize: 14, color: 'var(--muted)', marginTop: 16, animationDelay: '1.2s' }}>{t('hero.facts')}</p>
                        <div className="scroll-cue rise" style={{ animationDelay: '1.6s' }}><i />{t('hero.scroll')}</div>
                    </div>
                    <div className="rise" style={{ animationDelay: '.8s' }}><div className="phone"><div className="scr"><img className="on" src="/images/niyyah/welcome.jpg" alt={t('hero.alt')} /></div></div></div>
                </div>
            </section>

            <section data-sky="dhuhr">
                <div className="wrap" style={{ width: '100%' }}>
                    <div className="hadith reveal">
                        <p className="ar" lang="ar">إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ</p>
                        {t('hadith.text') && <p className="en">{t('hadith.text')}</p>}
                        <p className="src">{t('hadith.src')}</p>
                    </div>
                    <div className="steps">
                        {t('steps', { returnObjects: true }).map(({ t: title, d }, i) => (
                            <div key={title} className="glass step reveal" style={{ transitionDelay: `${i * 120}ms` }}>
                                <div className="k"><span className="n">{i + 1}</span><span className="a" lang="ar">{STEPS_AR[i]}</span></div>
                                <h3 style={{ marginTop: 12 }}>{title}</h3><p>{d}</p>
                            </div>
                        ))}
                    </div>
                    <p className="note reveal" style={{ maxWidth: 620, marginTop: 34 }}>{t('effortNote')}</p>
                </div>
            </section>

            <section data-sky="asr" id="try">
                <div className="wrap" style={{ width: '100%' }}><TryIt /></div>
            </section>

            <section data-sky="maghrib">
                <div className="wrap days">
                    <div className="reveal">
                        <span className="eyebrow">{t('week.eyebrow')}</span>
                        <h2 style={{ marginTop: 14 }}>{rich('week.h2')}</h2>
                        <p className="lede" style={{ marginTop: 18 }}>{t('week.lede')}</p>
                        <div className="week" aria-label={t('week.label')}>
                            {days.map((d, i) => <div key={d} className={`bud${i < open ? ' open' : ''}`}><Bloom /><span>{d}</span></div>)}
                        </div>
                    </div>
                    <div className="reveal">
                        <div className="phone"><div className="scr">{shots.map(([f, alt], i) => <img key={f} className={i === shot ? 'on' : ''} src={`/images/niyyah/${f}.jpg`} alt={alt} loading="lazy" />)}</div></div>
                        <p style={{ textAlign: 'center', color: 'var(--muted)', fontSize: 14, marginTop: 14 }}>{shots[shot][1]}</p>
                    </div>
                </div>
            </section>

            <section data-sky="isha">
                <div className="wrap" style={{ width: '100%' }}>
                    <span className="eyebrow reveal">{t('care.eyebrow')}</span>
                    <h2 className="reveal" style={{ marginTop: 14 }}>{rich('care.h2')}</h2>
                    <div className="grid3">{t('care.items', { returnObjects: true }).map(({ t: title, d }, i) => <div key={title} className="glass reveal" style={{ transitionDelay: `${(i % 3) * 120}ms` }}><h3>{title}</h3><p>{d}</p></div>)}</div>
                    <div className="ayah reveal">
                        <p className="ar" lang="ar">{AYAH_13_28_AR} ﴿{arNum(28)}﴾</p>
                        {t('ayah.en') && <p className="en">“{t('ayah.en')}”</p>}
                        <p className="src">{t('ayah.src')}</p>
                    </div>
                </div>
            </section>

            <section data-sky="isha" style={{ minHeight: 'auto' }}>
                <div className="wrap" style={{ width: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 80 }}>
                    <div className="faq reveal">
                        <span className="eyebrow">{t('faq.eyebrow')}</span>
                        <h2 style={{ marginTop: 14, marginBottom: 20 }}>{rich('faq.h2')}</h2>
                        {faq.map(({ q, a }) => <details key={q}><summary>{q}</summary><p>{a}</p></details>)}
                    </div>
                    <div className="final reveal">
                        <div className="rosette" style={{ maxWidth: 420, margin: '0 auto 28px' }} aria-hidden="true"><Rose /></div>
                        <h2>{rich('final.h2')}</h2>
                        <p className="lede" style={{ margin: '16px auto 0' }}>{t('final.lede')}</p>
                        <div className="ctas"><a className="btn gold" href={APP}>{t('hero.begin')}</a><RouterLink className="btn ghost" to="/alexa-skill">{t('final.alexa')}</RouterLink></div>
                    </div>
                </div>
            </section>
        </div>
    );
};

export default NiyyahPage;
